888	Status SegmentImpl::internal_upsert(Doc &doc) {
889	  uint64_t g_doc_id;
890	  bool exist = id_map_->has(doc.pk(), &g_doc_id);
891	  if (exist) {
892	    delete_store_->mark_deleted(g_doc_id);
893	  }
894	  return internal_insert(doc);
895	}
896	
897	Status SegmentImpl::internal_delete(const Doc &doc) {
898	  delete_store_->mark_deleted(doc.doc_id());
899	  id_map_->remove(doc.pk());
900	  return Status::OK();
901	}
