903	Status SegmentImpl::Insert(Doc &doc) {
904	  std::lock_guard lock(seg_mtx_);
905	
906	  if (id_map_ && id_map_->has(doc.pk())) {
907	    return Status::AlreadyExists("insert failed: doc_id[", doc.pk(),
908	                                 "] already exists in collection");
909	  }
910	
911	  doc.set_operator(Operator::INSERT);
912	
913	  // append wal
914	  auto s = append_wal(doc);
915	  CHECK_RETURN_STATUS(s);
916	
917	  return internal_insert(doc);
918	}
919	
920	Status SegmentImpl::Update(Doc &doc) {
921	  std::lock_guard lock(seg_mtx_);
922	  uint64_t g_doc_id;
923	  if (!id_map_->has(doc.pk(), &g_doc_id)) {
924	    return Status::NotFound("update failed: doc_id[", doc.pk(),
925	                            "] not found in collection");
926	  }
927	
928	  doc.set_doc_id(g_doc_id);
929	  doc.set_operator(Operator::UPDATE);
930	
931	  // append wal
932	  auto s = append_wal(doc);
933	  CHECK_RETURN_STATUS(s);
934	
935	  return internal_update(doc);
936	}
937	
938	Status SegmentImpl::Upsert(Doc &doc) {
939	  std::lock_guard lock(seg_mtx_);
940	
941	  doc.set_operator(Operator::UPSERT);
942	
943	  // append wal
944	  auto s = append_wal(doc);
945	  CHECK_RETURN_STATUS(s);
946	
947	  return internal_upsert(doc);
948	}
949	
950	Status SegmentImpl::Delete(const std::string &pk) {
951	  std::lock_guard lock(seg_mtx_);
952	
953	  uint64_t g_doc_id;
954	  if (!id_map_->has(pk, &g_doc_id)) {
955	    return Status::NotFound("primary key: ", pk, " not found");
956	  }
957	  if (delete_store_->is_deleted(g_doc_id)) {
958	    return Status::NotFound("primary key: ", pk, " g_doc_id: ", g_doc_id,
959	                            " already deleted");
960	  }
961	
962	  Doc mutable_doc;
963	  mutable_doc.set_pk(pk);
964	  mutable_doc.set_doc_id(g_doc_id);
965	  mutable_doc.set_operator(Operator::DELETE);
966	
967	  // append wal
968	  auto s = append_wal(mutable_doc);
969	  CHECK_RETURN_STATUS(s);
970	
971	  return internal_delete(mutable_doc);

